const wavPath = path.join(profileDir, 'tone.wav')
const wavSampleRate = 8000
const wavSamples = wavSampleRate * 2
const wavBytes = Buffer.alloc(44 + wavSamples * 2)
wavBytes.write('RIFF', 0); wavBytes.writeUInt32LE(wavBytes.length - 8, 4); wavBytes.write('WAVEfmt ', 8)
wavBytes.writeUInt32LE(16, 16); wavBytes.writeUInt16LE(1, 20); wavBytes.writeUInt16LE(1, 22)
wavBytes.writeUInt32LE(wavSampleRate, 24); wavBytes.writeUInt32LE(wavSampleRate * 2, 28)
wavBytes.writeUInt16LE(2, 32); wavBytes.writeUInt16LE(16, 34); wavBytes.write('data', 36); wavBytes.writeUInt32LE(wavSamples * 2, 40)
for (let sample = 0; sample < wavSamples; sample += 1) wavBytes.writeInt16LE(Math.round(Math.sin(2 * Math.PI * 440 * sample / wavSampleRate) * 5000), 44 + sample * 2)
await writeFile(wavPath, wavBytes)
